-- E-Trade organizado igual às pastas do canal VR Tech: um módulo por pasta (principais vídeos de cada uma).
-- Os 46 vídeos web vão para o módulo E-Trade Web;
UPDATE lessons l JOIN modules m ON m.module_id = l.module_id JOIN modules w ON w.system_id = 'e-trade' AND w.name = 'E-Trade Web' SET l.module_id = w.module_id, l.position = 100 + l.position WHERE m.system_id = 'e-trade' AND m.name = 'Primeiros passos' AND l.video_source = 'youtube' AND l.origin = 'admin' AND l.created_by IS NULL;
UPDATE lessons l JOIN modules m ON m.module_id = l.module_id JOIN modules w ON w.system_id = 'e-trade' AND w.name = 'E-Trade Web' SET l.module_id = w.module_id, l.position = 200 + l.position WHERE m.system_id = 'e-trade' AND m.name = 'Cadastros' AND l.video_source = 'youtube' AND l.origin = 'admin' AND l.created_by IS NULL;
