UPDATE lessons l JOIN modules m ON m.module_id = l.module_id JOIN modules w ON w.system_id = 'e-trade' AND w.name = 'E-Trade Web' SET l.module_id = w.module_id, l.position = 700 + l.position WHERE m.system_id = 'e-trade' AND m.name = 'Financeiro' AND l.video_source = 'youtube' AND l.origin = 'admin' AND l.created_by IS NULL;
UPDATE lessons l JOIN modules m ON m.module_id = l.module_id JOIN modules w ON w.system_id = 'e-trade' AND w.name = 'E-Trade Web' SET l.module_id = w.module_id, l.position = 800 + l.position WHERE m.system_id = 'e-trade' AND m.name = 'Relatórios' AND l.video_source = 'youtube' AND l.origin = 'admin' AND l.created_by IS NULL;
UPDATE lessons l JOIN modules m ON m.module_id = l.module_id JOIN modules w ON w.system_id = 'e-trade' AND w.name = 'E-Trade Web' SET l.module_id = w.module_id, l.position = 900 + l.position WHERE m.system_id = 'e-trade' AND m.name = 'Ordem de serviço' AND l.video_source = 'youtube' AND l.origin = 'admin' AND l.created_by IS NULL;
UPDATE lessons l JOIN modules m ON m.module_id = l.module_id JOIN modules w ON w.system_id = 'e-trade' AND w.name = 'E-Trade Web' SET l.module_id = w.module_id, l.position = 1000 + l.position WHERE m.system_id = 'e-trade' AND m.name = 'Integrações' AND l.video_source = 'youtube' AND l.origin = 'admin' AND l.created_by IS NULL;
DELETE m FROM modules m WHERE m.system_id = 'e-trade' AND m.name IN ('Primeiros passos','Cadastros','Produtos e estoque','Vendas e faturamento','Emissão de NF-e e NFC-e','Frente de caixa (PDV)','Financeiro','Relatórios','Ordem de serviço','Integrações') AND NOT EXISTS (SELECT 1 FROM lessons l WHERE l.module_id = m.module_id);
UPDATE modules SET position = 2, icon = 'cart' WHERE system_id = 'e-trade' AND name = 'Comercial';
